function localDateKey(value:Date=new Date()){return `${value.getFullYear()}-${String(value.getMonth()+1).padStart(2,'0')}-${String(value.getDate()).padStart(2,'0')}`}
function dobFromAge(years:number,months:number,days:number,asOf=new Date()){
 const d=new Date(Date.UTC(asOf.getFullYear(),asOf.getMonth(),asOf.getDate()));
 const clampDay=(year:number,month:number,day:number)=>Math.min(day,new Date(Date.UTC(year,month+1,0)).getUTCDate());
 let y=d.getUTCFullYear()-years,m=d.getUTCMonth(),day=d.getUTCDate();day=clampDay(y,m,day);d.setUTCFullYear(y,m,day);
 const total=d.getUTCFullYear()*12+d.getUTCMonth()-months;
 y=Math.floor(total/12);m=((total%12)+12)%12;day=clampDay(y,m,d.getUTCDate());d.setUTCFullYear(y,m,day);
 d.setUTCDate(d.getUTCDate()-days);
 return `${d.getUTCFullYear()}-${String(d.getUTCMonth()+1).padStart(2,'0')}-${String(d.getUTCDate()).padStart(2,'0')}`;
}

